test('reverse-sync: no configuration falls back to .pHive', async () => {
  const root = makeTmpDir();
  const stateDir = path.join(root, '.pHive');
  writeRunMarker(stateDir);
  const storyPath = writeStoryYaml(stateDir, { status: 'pending' });

